# Fix broken favicon.ico (currently just a blank gradient with no logo)
# and copy the branded icon into src/assets/images/logo/favi.png.
# Run once from the project root: powershell -ExecutionPolicy Bypass -File fix-favicon.ps1

$icoBase64 = ""

[IO.File]::WriteAllBytes("public\favicon.ico", [Convert]::FromBase64String($icoBase64))
Write-Host "Rewrote public/favicon.ico with the correct SSM logo icon."

Copy-Item "public\favicon.png" "src\assets\images\logo\favi.png" -Force
Write-Host "Copied public/favicon.png to src/assets/images/logo/favi.png."

Write-Host "Done. Restart npm run dev and hard-refresh (or open an Incognito window) to see the updated favicon."
